import { createPublicClient, createWalletClient, http, parseEther } from "viem";
import { privateKeyToAccount } from "viem/accounts";
import fs from "fs-extra";
import path from "path";

// Counter contract ABI and bytecode
const CounterABI = [
  {
    "inputs": [],
    "name": "getCount",
    "outputs": [{"internalType": "uint256", "name": "", "type": "uint256"}],
    "stateMutability": "view",
    "type": "function"
  },
  {
    "inputs": [],
    "name": "increment",
    "outputs": [],
    "stateMutability": "nonpayable",
    "type": "function"
  },
  {
    "inputs": [],
    "name": "decrement",
    "outputs": [],
    "stateMutability": "nonpayable",
    "type": "function"
  }
] as const;

const CounterBytecode = "";

async function main() {
  console.log("🚀 Starting simple Viem deployment...");

  const rpcUrl = process.env.ESPACE_RPC_URL || "http://localhost:8545";
  const privateKey = process.env.PRIVATE_KEY || "0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80";

  try {
    // Create clients
    const publicClient = createPublicClient({
      transport: http(rpcUrl),
    });

    const account = privateKeyToAccount(privateKey as `0x${string}`);
    const walletClient = createWalletClient({
      account,
      transport: http(rpcUrl),
    });

    // Check connection
    const chainId = await publicClient.getChainId();
    console.log(`🔗 Connected to Conflux EVM space, Chain ID: ${chainId}`);

    // Deploy Counter contract
    console.log("📦 Deploying Counter contract...");
    const counterHash = await walletClient.deployContract({
      abi: CounterABI,
      bytecode: CounterBytecode as `0x${string}`,
      account,
    });

    console.log(`⏳ Counter deployment transaction: ${counterHash}`);

    // Wait for deployment
    const counterReceipt = await publicClient.waitForTransactionReceipt({
      hash: counterHash,
    });

    if (!counterReceipt.contractAddress) {
      throw new Error("Counter contract deployment failed");
    }

    console.log(`✅ Counter deployed at: ${counterReceipt.contractAddress}`);

    // Update deployment file
    const counterDeployment = {
      address: counterReceipt.contractAddress,
      mock: false,
      timestamp: new Date().toISOString(),
    };

    await fs.writeJson(
      path.join(__dirname, "../deployment/deployments/counter.json"),
      counterDeployment,
      { spaces: 2 }
    );

    console.log("📝 Counter deployment file updated");
    console.log("🎉 Deployment completed successfully!");

  } catch (error) {
    console.error("❌ Deployment failed:", error);
    process.exit(1);
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
